/*
 * One valid frame per modelled method, and one valid payload per reply.
 *
 * These are not decoration. Three things depend on them:
 *
 *   1. **Coverage.** `envelope.test.ts` asserts there is exactly one example
 *      per modelled method and none for an unmodelled one, so a method added
 *      to a tier without a frame — or a frame added without a method — fails.
 *   2. **The negative battery.** Every malformed-input test in this package is
 *      generated by mutating one of these: wrong method tag, wrong kind, extra
 *      key, each key deleted in turn, each key given a wrong scalar type. A
 *      schema that stopped rejecting any of those fails a test named after the
 *      field.
 *   3. **Consumers.** A bridge or a UI needs a frame to test against before
 *      either end exists, and a shared one beats each side inventing its own.
 *
 * They are typed `unknown` on purpose. A `ServerFrame`-typed table would be
 * checked by the compiler and so could not express the malformed cases the
 * battery builds from it, and — worse — it would make the positive tests
 * tautological: "a value the type system already accepted parses". Parsing
 * these is a real assertion.
 *
 * There is no Tier C example here. `tier-c.test.ts` parses real packets
 * captured from a Forge match instead, which a hand-built example could only
 * approximate.
 */

const CARD = { kind: 'card', id: 101 } as const;
